LINK_STATE_CONFIG_KEYS = frozenset({"ports", "delay"})
LINK_STATE_PORT_KEYS = frozenset({"name", "rates", "modes"})
LINK_STATE_EVENT_KEYS = frozenset(
    {"t", "port", "admin", "peer", "rates", "modes"}
)
LINK_STATE_RATES = (10, 100, 1000, 10000)
LINK_STATE_MODES = ("half", "full")


def _validate_link_state_rates(rates):
    # rates 为 10/100/1000/10000 的非空严格递增子集
    if not isinstance(rates, list) or not rates:
        raise InvalidInput("bad rates")
    if any(
        not _is_int(rate) or rate not in LINK_STATE_RATES for rate in rates
    ):
        raise InvalidInput("bad rates")
    if any(rates[i] >= rates[i + 1] for i in range(len(rates) - 1)):
        raise InvalidInput("rates not increasing")
    return tuple(rates)


def _validate_link_state_modes(modes):
    # modes 为 half/full 的非空子序列（保序、互异、非空）
    if not isinstance(modes, list) or not modes:
        raise InvalidInput("bad modes")
    if any(
        not isinstance(mode, str) or mode not in LINK_STATE_MODES
        for mode in modes
    ):
        raise InvalidInput("bad modes")
    if len(set(modes)) != len(modes):
        raise InvalidInput("bad modes")
    if list(modes) != sorted(modes, key=LINK_STATE_MODES.index):
        raise InvalidInput("modes not a subsequence")
    return tuple(modes)


def validate_link_state_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != LINK_STATE_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    delay = config["delay"]
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    ports = config["ports"]
    if not isinstance(ports, list) or not ports:
        raise InvalidInput("ports must be a non-empty list")
    names = []
    result = []
    for port in ports:
        if (
            not isinstance(port, dict)
            or frozenset(port) != LINK_STATE_PORT_KEYS
        ):
            raise InvalidInput("bad port")
        name = port["name"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        names.append(name)
        result.append(
            (
                name,
                _validate_link_state_rates(port["rates"]),
                _validate_link_state_modes(port["modes"]),
            )
        )
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    return result, delay


def validate_link_state_events(events, ports):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    port_set = {name for name, _, _ in ports}
    result = []
    prev_t = None
    for event in events:
        if (
            not isinstance(event, dict)
            or frozenset(event) != LINK_STATE_EVENT_KEYS
        ):
            raise InvalidInput("bad event")
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        port = event["port"]
        if not isinstance(port, str) or port not in port_set:
            raise InvalidInput("unknown port")
        admin = event["admin"]
        peer = event["peer"]
        if not isinstance(admin, bool) or not isinstance(peer, bool):
            raise InvalidInput("bad admin/peer")
        rates = _validate_link_state_rates(event["rates"])
        modes = _validate_link_state_modes(event["modes"])
        result.append((t, port, admin, peer, rates, modes))
    return result


def link_state(events, ports, delay):
    caps = {name: (rates, modes) for name, rates, modes in ports}
    # 生效状态：("down",)/("bad",)/("up", rate, mode)；两状态初始皆 false
    committed = {name: ("down",) for name, _, _ in ports}
    pending = {}  # name -> (rate, mode, deadline)；仅 up 目标需协商
    results = []
    for t, port, admin, peer, rates, modes in events:
        # 先完成截止 <= t 的协商
        for name in [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        # 再替换该口并计算目标
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            pass  # 未变不重置
        elif target[0] == "up":
            # 目标变化即进入 wait 并于 t+delay 完成
            pending[port] = (target[1], target[2], t + delay)
        else:
            # down/bad 立即生效
            pending.pop(port, None)
            committed[port] = target
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
            else:
                state, rate, mode = now[0], None, None
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )
    return {"results": results}


def link_state_work(events, ports, delay, limit):
    """link-state 的工作量预演：独立 committed/pending 状态，无副作用。

    W 初值 0；逐事件在完成截止 <= t 的协商前，令 Q 为 pending 数，累计
    Q+1；再沿用 link_state 规则完成到期项、替换该口状态并计算
    down/bad/up 目标，目标未变不重置，变为 up 则进入 wait。等于上限
    合法，首次超过即抛 LinkWorkLimit，不访问后续事件。
    """
    caps = {name: (rates, modes) for name, rates, modes in ports}
    committed = {name: ("down",) for name, _, _ in ports}
    pending = {}  # name -> (rate, mode, deadline)
    work = 0
    for t, port, admin, peer, rates, modes in events:
        work += len(pending) + 1
        if work > limit:
            raise LinkWorkLimit()
        for name in [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            pass  # 未变不重置
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
        else:
            pending.pop(port, None)
            committed[port] = target


LINK_FORWARD_CONFIG_KEYS = frozenset(
    {"ports", "age", "max_frame", "delay"}
)
LINK_FORWARD_LINK_EVENT_KEYS = LINK_STATE_EVENT_KEYS
LINK_FORWARD_FRAME_EVENT_KEYS = FORWARD_CHECK_FRAME_KEYS


def validate_link_forward_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != LINK_FORWARD_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    delay = config["delay"]
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    # ports/age 与新式 forward 契约一致；每口删 up、增 rates/modes，
    # rates/modes 约束同 link-state 端口
    age = config["age"]
    if not _is_int(age) or age <= 0:
        raise InvalidInput("age must be a positive integer")
    port_docs = config["ports"]
    if not isinstance(port_docs, list) or not port_docs:
        raise InvalidInput("ports must be a non-empty list")
    names = []
    caps = {}
    fwd_ports = []
    for port in port_docs:
        if not isinstance(port, dict) or frozenset(port) != (
            PORT_KEYS_V2 - {"up"}
        ) | {"rates", "modes"}:
            raise InvalidInput("bad port")
        name = port["name"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        names.append(name)
        rates = _validate_link_state_rates(port["rates"])
        modes = _validate_link_state_modes(port["modes"])
        caps[name] = (rates, modes)
        # 其余字段约束同新式 forward 端口（补恒为 false 的 up）
        fwd_ports.append(
            {
                "name": name,
                "mode": port["mode"],
                "pvid": port["pvid"],
                "allowed": port["allowed"],
                "untagged": port["untagged"],
                "up": False,
            }
        )
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    # 复用新式 forward 端口全量校验（mode/pvid/allowed/untagged）
    validate_forward_config_v2({"ports": fwd_ports, "age": age})
    return fwd_ports, caps, age, max_frame, delay


def validate_link_forward_events(events, fwd_ports):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in fwd_ports}
    result = []
    prev_t = None
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == LINK_FORWARD_LINK_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            port = event["port"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            admin = event["admin"]
            peer = event["peer"]
            if not isinstance(admin, bool) or not isinstance(peer, bool):
                raise InvalidInput("bad admin/peer")
            rates = _validate_link_state_rates(event["rates"])
            modes = _validate_link_state_modes(event["modes"])
            result.append(("link", t, port, admin, peer, rates, modes))
        elif keys == LINK_FORWARD_FRAME_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            port = event["port"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            src = event["src"]
            dst = event["dst"]
            tag = event["vlan"]
            length = event["length"]
            fcs = event["fcs"]
            alignment = event["alignment"]
            if not valid_mac(src):
                raise InvalidInput("bad src")
            if dst != BROADCAST_MAC and not valid_mac(dst):
                raise InvalidInput("bad dst")
            if tag is not None and not _valid_vlan_id(tag):
                raise InvalidInput("bad vlan")
            if not _is_int(length) or length < 0:
                raise InvalidInput("bad length")
            if not isinstance(fcs, bool):
                raise InvalidInput("bad fcs")
            if not isinstance(alignment, bool):
                raise InvalidInput("bad alignment")
            result.append(
                ("frame", t, port, src, dst, tag, length, fcs, alignment)
            )
        else:
            raise InvalidInput("bad event")
        prev_t = t
    return result


def link_forward(
    fwd_ports, caps, age, max_frame, delay, events, observer=None
):
    if observer is not None:  # record：逐事件记录 applied 与对应 results 项
        observer["items"] = []
    by_name = {port["name"]: port for port in fwd_ports}
    # 协商状态：("down",)/("bad",)/("up", rate, mode)；初始皆 down
    committed = {name: ("down",) for name in by_name}
    pending = {}  # name -> (rate, mode, deadline)；仅 up 目标需协商
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {
        name: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for name in by_name
    }
    vlan_stats = {}
    for port in fwd_ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []

    def settle(t):
        # 完成截止 <= t 的协商，返回到期口名（保序同 link-state）
        due = [
            name
            for name, (_, _, deadline) in pending.items()
            if deadline <= t
        ]
        for name in due:
            rate, mode, _ = pending.pop(name)
            committed[name] = ("up", rate, mode)
        return due

    def apply_link(t, port, admin, peer, rates, modes):
        settle(t)
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        # 变更前的有效态：在 wait（pending 未完成）即非 up
        before_up = port not in pending and committed[port][0] == "up"
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            applied = False  # 未变不重置
        elif target[0] == "up":
            # 目标变化即进入 wait 并于 t+delay 完成
            pending[port] = (target[1], target[2], t + delay)
            applied = True
        else:
            # down/bad 立即生效
            pending.pop(port, None)
            committed[port] = target

    total = 0
    while True:
        remaining = limit - total
        if remaining > 0:
            chunk = handle.read(min(_READ_CHUNK, remaining))
        else:
            chunk = handle.read(1)
        if not chunk:
            return b"".join(chunks)
        chunks.append(chunk)
        total += len(chunk)
        if total > limit:
            return None


RECORD_SCHEMA = 1
LOG_KEYS = ("schema", "config", "records", "sha256")
RECORD_KEYS = ("t", "version", "event", "applied", "output")
EVENT_KIND_BY_KEYS = {
    STP_EVENT_KEYS: "link",
    MEMBER_EVENT_KEYS: "member",
    SERVICE_EVENT_KEYS: "service",
    FRAME_KEYS_ACL: "frame",
    RELOAD_EVENT_KEYS: "reload",
    ROLLBACK_EVENT_KEYS: "rollback",
    LINK_FORWARD_LINK_EVENT_KEYS: "link",
    LINK_FORWARD_FRAME_EVENT_KEYS: "frame",
}
_HEX64_RE = re.compile(r"[0-9a-f]{64}\Z")


def _event_kind(event):
    if not isinstance(event, dict):
        raise InvalidInput("bad log event")
    kind = EVENT_KIND_BY_KEYS.get(frozenset(event))
    if kind is None:
        raise InvalidInput("bad log event")
    return kind


def _log_mode(config):
    """record/replay 按 config 形状选模式：loop-detect、link-forward 或 port-security。"""
    if isinstance(config, dict):
        keys = frozenset(config)
        if keys == LOOP_CONFIG_KEYS:
            return "loop"
        if keys == LINK_FORWARD_CONFIG_KEYS:
            return "link_forward"
    return "security"


def _run_loop_detect(config, events, observe, max_work=None):
    """record/replay 环路模式：校验 loop-detect 配置与事件并执行仿真。

    语义同 loop-detect 子命令；工作量预演（V*(L+1)*(事件数+1)）在
    loop_detect 内、正式仿真前无副作用完成，超限抛 LoopWorkLimit。
    返回 (loop-detect 结果 dict, observer 或 None)。
    """
    bridges, links, vlans = validate_loop_detect_config(config)
    link_ids = {link["id"] for link in links}
    stp_events = validate_stp_events(events, link_ids)
    observer = {} if observe else None
    result = loop_detect(
        links, vlans, stp_events, max_work, observer=observer
    )
    return result, observer


def _run_reload(config, events, observe, max_work=None):
    """reload/record/replay 共用：校验配置与事件并执行 port-security 仿真。

    事件允许 {t, rollback} 回滚事件（语义同 reload-rollback 子命令）。
    返回 (reload 结果 dict, observer 或 None)。全部校验与非法重载检测先于返回。
    max_work 非 None 时（record），全量语义校验后先按 reload 公式无副作用
    预演；首次超过即抛 ReloadWorkLimit，不正式仿真。
    """
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
    ) = validate_security_config(config)
    link_ids = {link["id"] for link in links}
    reload_events, final_config = validate_reload_events(
        events, ports, link_ids, lags, config, allow_rollback=True
    )
    if max_work is not None:
        # 与 reload 入口同一公式：独立链路副本与空状态，不改动既有数据
        reload_work(
            bridges,
            links,
            delay,
            bridge,
            ports,
            age,
            storm,
            lags,
            acl,
            qos,
            security,
            reload_events,
            max_work,
        )
    observer = {} if observe else None
    result = forward_security(
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
        reload_events,
        observer=observer,
    )
    result["config"] = _canonical(final_config)
    return result, observer


def _run_link_forward(config, events, observe, max_work=None):
    """record/replay 链路协商模式：校验 link-forward 配置与事件并执行仿真。

    语义同 link-forward 子命令；max_work 非 None 时全量语义校验后先按
    link-forward 公式无副作用预演，首次超过即抛 LinkForwardWorkLimit，
    不正式仿真。返回 (link-forward 结果 dict, observer 或 None)。
    """
    fwd_ports, caps, age, max_frame, delay = validate_link_forward_config(
        config
    )
    lf_events = validate_link_forward_events(events, fwd_ports)
    if max_work is not None:
        # 与 link-forward 入口同一公式：只计端口数与此前帧数，无副作用
        link_forward_work(fwd_ports, lf_events, max_work)
    observer = {} if observe else None
    result = link_forward(
        fwd_ports, caps, age, max_frame, delay, lf_events, observer=observer
    )
    return result, observer


def _build_log_doc(config, events, items):
    """构造 LOG 文档（含 sha256）；records 与事件等长、同序。"""
    if len(events) != len(items):
        raise InvalidInput("bad log")
    mode = _log_mode(config)
    records = []
    # version 初值 0，取事件后值；安全模式每次 reload/rollback（无变化
    # 亦算）加 1，环路模式链路 up 实际改变（applied）才加 1，链路协商
    # 模式仅 applied 链路项加 1（帧项恒 applied 但不计）
    version = 0
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if mode == "loop":
            if observed["applied"]:
                version += 1
        elif mode == "link_forward":
            if kind == "link" and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _log_bytes(doc):
    ordered = {key: doc[key] for key in LOG_KEYS}
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _assert_canonical_order(value):
    """config/event 内对象键须递归按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        keys = list(value)
        if keys != sorted(keys):
            raise InvalidInput("bad log key order")
        for item in value.values():
            _assert_canonical_order(item)
    elif isinstance(value, list):
        for item in value:
            _assert_canonical_order(item)


def _json_equal(a, b):
    """JSON 值深比较；bool 不与 int 混同，键序无关，数组保序。"""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            _json_equal(a[key], b[key]) for key in a
        )
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(
            _json_equal(x, y) for x, y in zip(a, b)
        )
    if a is None or b is None:
        return a is None and b is None
    return type(a) is type(b) and a == b


def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
        _event_kind(event)
        if not isinstance(record["applied"], bool):
            raise InvalidInput("bad log applied")
        if record["output"] is not None and not isinstance(
