            _fail("output_limit")
            return 5
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (ReloadWorkLimit, LoopWorkLimit, LinkForwardWorkLimit):
        _fail("replay_work_limit")
        return 5
    sys.stdout.buffer.write(output)
    return 0


